1	// THE TERMINAL TRANSITION, IN CODE (#892; tasks-dispatch DESIGN §6.5, §15.18,
2	// §15.19). A work-item session ends by performing five ordered side effects —
3	// comment, drop `task:agent`, add the outcome label, carry the execution record,
4	// close with the right state reason — and then releasing whatever the close
5	// freed. Asking a session to do that from prose is asking for it at the moment
6	// its context is fullest and the remaining work looks like formality; both of the
7	// first two live agentic runs got part of it wrong, silently, in different ways.
8	//
9	// The split is the same one the executor already draws: THE SESSION SUPPLIES THE
10	// JUDGMENT — which outcome, and the prose of what happened — and the CODE
11	// performs the transition. A session that stops early now leaves an item that is
12	// visibly unconverged, rather than one that looks finished and is not.
13	//
14	// Usage:
15	//   node converge-item.mjs --issue <n> --outcome <done|approval|action|decision|failure>
16	//                          --summary <text> [--pr <n>]
17	
18	import { pathToFileURL } from 'node:url';
19	import { renderTaskExec } from '../run-record.mjs';
20	import { readyDependents } from './readiness.mjs';
21	import { swapStatus, clearStatus } from './apply-status.mjs';
22	import {
23	  AGENT, NEEDS_HUMAN, TASK_DONE, STATUS_RUNNING_AGENT, isStatus, isWorkItemTitle, machineBlockOf,
24	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_FAILURE,
25	  QUEUED_LABEL, IN_REVIEW_LABEL,
26	  parseWorkItemTitle, parseWorkItemBody,
27	} from './work-item.mjs';
28	
29	// What a session may claim, and what each one means for the item. `record` is the
30	// execution-record status, and `null` means no record: an approval park is a run
31	// that SUCCEEDED and left a PR, which the record vocabulary has no word for, and
32	// a fifth status would be stored data every decoder in the fleet must learn.
33	export const OUTCOMES = Object.freeze({
34	  done: { label: TASK_DONE, closes: true, stateReason: 'completed', record: 'success' },
35	  approval: { label: NEEDS_HUMAN_APPROVAL, closes: false, record: null },
36	  action: { label: NEEDS_HUMAN_ACTION, closes: false, record: 'failed' },
37	  decision: { label: NEEDS_HUMAN_DECISION, closes: false, record: 'failed' },
38	  failure: { label: NEEDS_HUMAN_FAILURE, closes: false, record: 'failed' },
39	});
40	
41	export function parseArgs(argv) {
42	  const args = {};
43	  for (let n = 0; n < argv.length; n += 1) {
44	    const m = /^--([a-z-]+)$/.exec(argv[n]);
45	    if (m) { args[m[1]] = argv[n + 1] ?? ''; n += 1; }
46	  }
47	  const issue = Number(args.issue);
48	  if (!Number.isInteger(issue) || issue <= 0) return { error: '--issue must be the work item\'s issue number' };
49	  if (!OUTCOMES[args.outcome]) {
50	    return { error: `--outcome must be one of ${Object.keys(OUTCOMES).join(', ')}, got ${JSON.stringify(args.outcome ?? null)}` };
51	  }
52	  if (!String(args.summary ?? '').trim()) return { error: '--summary must say what happened; it is the item\'s only durable account' };
53	  if (args.outcome === 'approval' && !args.pr) {
54	    return { error: '--pr must name the pull request an approval park is waiting on — a park nobody can act on is not a park' };
55	  }
56	  return { issue, outcome: args.outcome, summary: args.summary, pr: args.pr ? Number(args.pr) : null };
57	}
58	
59	// Why an item may NOT be converged by this call. Refusing loudly beats writing a
60	// terminal state onto the wrong issue: this runs from a session, whose whole
61	// notion of which item it holds came from an untrusted fire payload.
62	export function refusal(item, issue) {
63	  if (!item) return `#${issue} could not be read`;
64	  // A marked issue IS its own item (DESIGN §16.1), so the title test cannot be the
65	  // membership test any more: what says this is one is the machine block adoption
66	  // wrote — never the body's first line, which on a marked issue is a person's prose.
67	  if (!parseWorkItemTitle(item.title ?? '') && machineBlockOf(item.body ?? '') === null) {
68	    return `#${issue} is not a Claudinite work item`;
69	  }
70	  if (item.state !== 'open') return `#${issue} is already closed — it was converged once already`;
71	  if (!isStatus(item, STATUS_RUNNING_AGENT)) {
72	    return `#${issue} is not with an agent (\`${AGENT}\`) — this session does not hold it, so it is not this session's to converge`;
73	  }
74	  return null;
75	}
76	
77	// The record line for this item, or null where the vocabulary has no true answer.
78	export const recordLine = (item, status) => {
79	  const parsed = parseWorkItemTitle(item.title);
80	  return status && parsed
81	    ? renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })
82	    : null;
83	};
84	
85	// The comment one converge writes: the session's account, then the record, so a
86	// reader and a parser both find what they came for in one place.
87	export function convergeComment(item, { summary, pr, record }) {
88	  const rec = recordLine(item, record);
89	  const line = rec ? `\n\n\`\`\`\n${rec}\n\`\`\`` : '';
90	  const waiting = pr ? `\n\nWaiting on a person: merge or close #${pr}, then close this item.` : '';
91	  return `${summary.trim()}${waiting}${line}`;
92	}
93	
94	export async function convergeItem(api, gh, repo, plan, { now = () => new Date(), log = console.log } = {}) {
95	  const item = await api.readIssue(gh, repo, plan.issue);
96	  const no = refusal(item, plan.issue);
97	  if (no) return { ok: false, error: no };
98	
99	  const spec = OUTCOMES[plan.outcome];
100	  await api.comment(gh, repo, item.number, convergeComment(item, { ...plan, record: spec.record }));
101	  // The record goes to BOTH sinks, and neither is redundant: the comment is the
102	  // durable one (Actions logs expire, the item does not), while this printed copy
103	  // lands in the session transcript, which is what the usage fold reads for the
104	  // task-status census. The fold dedupes on the record's own tuple within a
105	  // capture file, so a line appearing in stdout and in the harness's echo of it
106	  // counts once.
107	  const rec = recordLine(item, spec.record);
108	  if (rec) log(rec);
109	  if (spec.closes) {
110	    await clearStatus(api, gh, repo, item, STATUS_RUNNING_AGENT);
111	    await api.addLabel(gh, repo, item.number, spec.label);
112	    // A MARKED ISSUE IS NOT THE SESSION'S TO CLOSE (§16.1, §16.5): the terminal
113	    // status stands on the open issue, and whether the issue itself is finished
114	    // belongs to the person who opened it. Nothing is released, because the issue a
115	    // dependent waits on has not closed.
116	    if (!isWorkItemTitle(item.title ?? '')) return { ok: true, closed: false, freed: [] };
117	    await api.closeIssue(gh, repo, item.number, spec.stateReason);
118	    // §15.19: whoever closes an item releases what it was holding.
119	    const freed = await readyDependents(api, gh, repo, item.number, { now, log });
120	    return { ok: true, closed: true, freed };
121	  }
122	  // Every park wears BOTH labels: `needs-human` is the state every guard and
123	  // sweep reads, the sub-label is what the person is being asked for.
124	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN);
125	  await api.addLabel(gh, repo, item.number, spec.label);
126	  // A REQUEST ITEM WRITES BACK TO ITS ISSUE, on the one end that is its business
127	  // (§16.5). Only the approval park: a failure deliberately writes nothing and
128	  // leaves `claude-queued` standing, because re-arming work that writes code is a
129	  // person's decision and that standing label is what stops the next scheduler run queueing
130	  // a second run of the same request.
131	  // Only a LEGACY shadow item writes back to a different issue: under the one-issue
132	  // model the approval park stands on the marked issue itself and IS the in-review
133	  // state, with nothing to mirror (§16.5).
134	  const { request } = parseWorkItemBody(item.body ?? '');
135	  if (request && request !== item.number && plan.outcome === 'approval') {
136	    await api.comment(gh, repo, request,
137	      `A pull request for this is open and waiting on you: #${plan.pr}. Merge or close it.`);
138	    await api.swapLabel(gh, repo, request, QUEUED_LABEL, IN_REVIEW_LABEL);
139	  }
140	  return { ok: true, closed: false, freed: [], request: request ?? null };
141	}
142	
143	async function main() {
144	  const plan = parseArgs(process.argv.slice(2));
145	  if (plan.error) {
146	    console.error(`converge-item: ${plan.error}`);
147	    process.exit(2);
148	  }
149	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
150	  const api = await import('../github.mjs');
151	  const { repo } = actionRepoContext();
152	  if (!repo) { console.error('converge-item: GITHUB_REPOSITORY is not set'); process.exit(1); }
153	
154	  const res = await convergeItem(api, makeGh(), repo, plan);
155	  if (!res.ok) { console.error(`converge-item: ${res.error}`); process.exit(1); }
156	  console.log(res.closed
157	    ? `converged #${plan.issue}: closed ${OUTCOMES[plan.outcome].label}`
158	      + (res.freed.length ? `, released ${res.freed.map((n) => `#${n}`).join(', ')}` : '')
159	    : `converged #${plan.issue}: parked ${OUTCOMES[plan.outcome].label}, left open for a person`);
160	}
161	
162	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
163	  main().catch((e) => { console.error(e); process.exit(1); });
164	}
